{
  "scenario_id": "sc-6e2478",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "~5x Poisson year-to-year dispersion (empirical YoY sd of A/E 0.25 vs ~0.05); annual A/E swings between ~0.72 and ~1.32 around a flat level of ~1.01",
      "confidence": 0.6,
      "evidence": [
        "ae_death_by_year.csv: A/E 1.03/1.17/1.32 (2015-17), 0.84 (2018), 1.06/0.97 (2019-20), 0.72/0.80 (2021-22), 1.11/1.13 (2023-24) - a peak-trough-peak oscillation; onset ratio 1.54 shows the line oscillates rather than holding a new level, and overall A/E is 1.001 (level flat)",
        "evidence pack DEATH: YoY sd 0.2495 vs Poisson 0.0477 (x5.23 overdispersion, profile 'scatter-dominant'); step -0.227 at 2018 (score 2.2); excursion 2021-22 -0.316 (score 4.9); max single-year moves 5-10x the Poisson-expected move",
        "Poisson z-scores are invalid for this line (overdispersed); scaled by the line's own sd, no single year is extreme - the elevated scatter itself is the material feature, and it is the only structured story in an otherwise clean book (CI, TPD, IP all 'no strong signal', IP termination by diagnosis all within ~1.7 sigma of assumed rates)"
      ],
      "recommended_action": "Do not flag individual Death years against the Poisson null. Investigate the source of the swings: large-claim clustering, claim year vs occurrence year assignment, reporting lags/data cuts, and the expected-claims basis (mortality table or exposure growth ~14%/yr) in 2017, 2018, 2021 and 2022-24; if the swings persist as genuine experience, widen Death monitoring tolerance bands to reflect the empirical dispersion (~+/-0.25) rather than the Poisson band."
    }
  ]
}

